-- Enum types used by these columns.
do $$ begin
  if not exists (select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace
                 where t.typname='answer_precedence' and n.nspname='public') then
    create type public.answer_precedence as enum ('customer_confirmed', 'approved_document', 'document_extracted', 'deterministic_inference', 'model_inference', 'unknown');
  end if;
end $$;
do $$ begin
  if not exists (select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace
                 where t.typname='gate_state' and n.nspname='public') then
    create type public.gate_state as enum ('not_evaluated', 'pending', 'passed', 'failed', 'blocked', 'not_applicable');
  end if;
end $$;

-- ── public.action_class_gate ─────────────────────────────────────────────────────────────
create table if not exists public.action_class_gate (
  action_class text,
  gate_action_class text,
  rationale text,
  reviewed_on date default CURRENT_DATE,
  reviewed_by text default 'founder'::text,
  constraint action_class_gate_known_gate CHECK (((gate_action_class IS NULL) OR (gate_action_class = ANY (ARRAY['ad_spend'::text, 'authentication_identity'::text, 'autonomy_framework'::text, 'destructive_data'::text, 'legal_commitment'::text, 'money_move'::text, 'production_deploy'::text, 'public_claim_publish'::text, 'secrets_security'::text, 'supplier_enforcement'::text])))),
  constraint action_class_gate_pkey PRIMARY KEY (action_class)
);
alter table public.action_class_gate enable row level security;

-- ── public.action_execution ──────────────────────────────────────────────────────────────
create table if not exists public.action_execution (
  id uuid default gen_random_uuid(),
  correlation_id uuid,
  workflow_step_run_id bigint,
  action_class text,
  executor text,
  idempotency_key text,
  risk_tier text,
  reversible boolean default false,
  request jsonb,
  response jsonb,
  status text default 'queued'::text,
  attempts integer default 0,
  compensation_action_class text,
  compensated_at timestamp with time zone,
  started_at timestamp with time zone,
  finished_at timestamp with time zone,
  created_at timestamp with time zone default now(),
  constraint action_execution_pkey PRIMARY KEY (id),
  constraint action_execution_idempotency_key_key UNIQUE (idempotency_key)
);
alter table public.action_execution enable row level security;
create index if not exists ix_action_execution_correlation ON public.action_execution USING btree (correlation_id);

