create unique index if not exists leads_founding_rank_uidx ON public.leads USING btree (founding_rank) WHERE (founding_rank IS NOT NULL);
create index if not exists leads_has_email_idx ON public.leads USING btree (((email IS NOT NULL)));
create index if not exists leads_invite_status_idx ON public.leads USING btree (invite_status);
create index if not exists leads_lifecycle_stage_idx ON public.leads USING btree (lifecycle_stage);
create unique index if not exists leads_place_id_uidx ON public.leads USING btree (place_id) WHERE (place_id IS NOT NULL);
create index if not exists leads_sector_idx ON public.leads USING btree (sector);
create unique index if not exists uq_leads_email_lower ON public.leads USING btree (lower(email)) WHERE ((email IS NOT NULL) AND (email <> ''::text));

