-- ── public.refunds ───────────────────────────────────────────────────────────────────────
create table if not exists public.refunds (
  id bigint default nextval('refunds_id_seq'::regclass),
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now(),
  inquiry_id uuid,
  customer_id uuid,
  supplier_lead_id bigint,
  original_txn_id bigint,
  stripe_payment_intent text,
  stripe_charge_id text,
  stripe_refund_id text,
  amount_fils bigint,
  currency text default 'AED'::text,
  reason_code text,
  reason_note text,
  status text default 'requested'::text,
  requested_by text,
  requested_at timestamp with time zone default now(),
  decided_by text,
  decided_at timestamp with time zone,
  decision_note text,
  within_auto_window boolean default false,
  settled_at timestamp with time zone,
  failure_reason text,
  gl_entry_id bigint,
  reconciled_at timestamp with time zone,
  reconciliation_note text,
  transaction_id uuid,
  quote_id uuid,
  amount_source text,
  constraint refunds_amount_fils_check CHECK (((amount_fils IS NULL) OR (amount_fils > 0))),
  constraint refunds_amount_source_check CHECK (((amount_source IS NULL) OR (amount_source = ANY (ARRAY['in_platform_request'::text, 'webhook_event'::text, 'stripe_api'::text, 'manual'::text, 'unknown'::text])))),
  constraint refunds_currency_check CHECK ((currency = 'AED'::text)),
  constraint refunds_reason_code_check CHECK ((reason_code = ANY (ARRAY['supplier_unresponsive'::text, 'supplier_withdrew'::text, 'duplicate_charge'::text, 'customer_cancelled_in_window'::text, 'service_not_delivered'::text, 'fraud_or_dispute'::text, 'goodwill'::text, 'other'::text]))),
  constraint refunds_settled_needs_amount CHECK (((status <> 'succeeded'::text) OR (amount_fils IS NOT NULL) OR (reconciliation_note IS NOT NULL))),
  constraint refunds_status_check CHECK ((status = ANY (ARRAY['requested'::text, 'approved'::text, 'rejected'::text, 'processing'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text]))),
  constraint refunds_pkey PRIMARY KEY (id),
  constraint refunds_stripe_refund_id_key UNIQUE (stripe_refund_id)
);
alter table public.refunds enable row level security;
create index if not exists refunds_customer_idx ON public.refunds USING btree (customer_id);
create index if not exists refunds_inquiry_idx ON public.refunds USING btree (inquiry_id);
create index if not exists refunds_status_idx ON public.refunds USING btree (status, created_at DESC);
create index if not exists refunds_stripe_pi_idx ON public.refunds USING btree (stripe_payment_intent);
create index if not exists refunds_transaction_idx ON public.refunds USING btree (transaction_id);
create index if not exists refunds_unreconciled_idx ON public.refunds USING btree (settled_at) WHERE ((reconciled_at IS NULL) AND (status = 'succeeded'::text));

