create index if not exists ix_workflow_run_status ON public.workflow_run USING btree (status, next_attempt_at);

-- ── public.workflow_step ─────────────────────────────────────────────────────────────────
create table if not exists public.workflow_step (
  workflow_key text,
  step_no integer,
  step text,
  actor_role text,
  action_class text,
  gate text,
  constraint workflow_step_pkey PRIMARY KEY (workflow_key, step_no)
);
alter table public.workflow_step enable row level security;

-- ── public.workflow_step_run ─────────────────────────────────────────────────────────────
create table if not exists public.workflow_step_run (
  id bigint default nextval('workflow_step_run_id_seq'::regclass),
  workflow_run_id uuid,
  step_no integer,
  actor text,
  action_class text,
  status text default 'queued'::text,
  input jsonb default '{}'::jsonb,
  output jsonb,
  idempotency_key text,
  attempts integer default 0,
  started_at timestamp with time zone,
  finished_at timestamp with time zone,
  error jsonb,
  constraint workflow_step_run_pkey PRIMARY KEY (id),
  constraint workflow_step_run_idempotency_key_key UNIQUE (idempotency_key),
  constraint workflow_step_run_workflow_run_id_step_no_key UNIQUE (workflow_run_id, step_no)
);
alter table public.workflow_step_run enable row level security;

-- ── public.yello_staging ─────────────────────────────────────────────────────────────────
create table if not exists public.yello_staging (
  company_id text,
  slug text,
  name text,
  city text,
  src_category text,
  profile_url text,
  website text,
  phone text,
  mobile text,
  whatsapp text,
  categories text[],
  manager text,
  established text,
  address text,
  email text,
  email_source text,
  sector text,
  stage text default 'listed'::text,
  note text,
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now(),
  constraint yello_staging_pkey PRIMARY KEY (company_id)
);
alter table public.yello_staging enable row level security;
create index if not exists yello_email_idx ON public.yello_staging USING btree (email);

-- ── public.zz_lead_hay ───────────────────────────────────────────────────────────────────
create table if not exists public.zz_lead_hay (
  id bigint,
  hay text,
  constraint zz_lead_hay_pkey PRIMARY KEY (id)
);
alter table public.zz_lead_hay enable row level security;
create index if not exists zz_lead_hay_trgm ON public.zz_lead_hay USING gin (hay gin_trgm_ops);
